-- 152: Original BrillaPrep WASSCE BrillaPrep transitional Electronics beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_152_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_152_guard;
INSERT INTO _migration_152_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_006' AND NOT (q.topic_id IS 'topic_was_electronics_b002_2' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Two resistors of 3 kΩ and 6 kΩ are in parallel. What is their equivalent resistance?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 9 kΩ","B. 2 kΩ","C. 4 kΩ","D. 4.5 kΩ"]' AND q.correct_answer IS 'B' AND q.explanation IS 'For two parallel resistors, the product divided by the sum gives 18 divided by 9 kilohms, which equals 2 kΩ. Therefore the correct answer is B: 2 kΩ.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_006' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_152_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_007' AND NOT (q.topic_id IS 'topic_was_electronics_b002_2' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What current flows through a 1 kΩ resistor connected across 5 V?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 0.005 mA","B. 0.2 mA","C. 5 mA","D. 5 A"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Ohm’s law gives current as voltage divided by resistance: 5 V divided by 1000 Ω equals 0.005 A or 5 mA. Therefore the correct answer is C: 5 mA.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_007' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_152_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_008' AND NOT (q.topic_id IS 'topic_was_electronics_b002_2' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What happens to an ideal capacitor after it is fully charged from a steady direct-current source?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It remains a short circuit to steady current","B. It loses all stored charge as soon as charging ends","C. It continues drawing its initial charging current indefinitely","D. It blocks steady current while retaining charge"]' AND q.correct_answer IS 'D' AND q.explanation IS 'After the transient charging current falls to zero, an ideal capacitor presents an open circuit to steady DC and stores electric-field energy. Therefore the correct answer is D: It blocks steady current while retaining charge.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_008' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_152_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_009' AND NOT (q.topic_id IS 'topic_was_electronics_b002_2' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which property of an inductor opposes a rapid change in its current?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Self-induced emf","B. The resistance of its winding alone","C. Electric-field capacitance","D. A mutually induced emf from the same coil"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Changing current changes magnetic flux, inducing an emf whose polarity opposes the change according to Lenz’s law. Therefore the correct answer is A: Self-induced emf.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_009' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_152_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_010' AND NOT (q.topic_id IS 'topic_was_electronics_b002_2' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a resistor placed in series with a light-emitting diode?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To hold the LED voltage at the full supply value","B. To limit current to a safe value","C. To bypass the LED whenever it conducts","D. To make the LED conduct equally in both directions"]' AND q.correct_answer IS 'B' AND q.explanation IS 'An LED has a steep current-voltage characteristic, so a series resistor drops excess voltage and controls current within the device rating. Therefore the correct answer is B: To limit current to a safe value.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_010' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_electronics_b002_006', 'topic_was_electronics_b002_2', 'subj_wassce_electronics', 'exam_wassce', NULL, NULL, 'Two resistors of 3 kΩ and 6 kΩ are in parallel. What is their equivalent resistance?', 'multiple_choice', NULL, '["A. 9 kΩ","B. 2 kΩ","C. 4 kΩ","D. 4.5 kΩ"]', 'B', 'For two parallel resistors, the product divided by the sum gives 18 divided by 9 kilohms, which equals 2 kΩ. Therefore the correct answer is B: 2 kΩ.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_electronics_b002_2', 'Identify', 'AO3', NULL, NULL, 'board_waec');
