INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_electronics_b002_009', 'topic_was_electronics_b002_2', 'subj_wassce_electronics', 'exam_wassce', NULL, NULL, 'Which property of an inductor opposes a rapid change in its current?', 'multiple_choice', NULL, '["A. Self-induced emf","B. The resistance of its winding alone","C. Electric-field capacitance","D. A mutually induced emf from the same coil"]', 'A', 'Changing current changes magnetic flux, inducing an emf whose polarity opposes the change according to Lenz’s law. Therefore the correct answer is A: Self-induced emf.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_electronics_b002_2', 'Identify', 'AO3', NULL, NULL, 'board_waec');
